        result = 0
        def dfs(i, j, count):
            nonlocal result
            if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == -1:
                return

            if grid[i][j] == 2:
                if count == total_empty:
                    result += 1
                return

            temp = grid[i][j]
            grid[i][j] = -1  # mark visited

            dfs(i+1, j, count+1)
            dfs(i-1, j, count+1)
            dfs(i, j+1, count+1)
